INSERT INTO `email_templates` (`id`, `type`, `subject`, `to`, `template`, `bcc`, `cc`, `parameters`) VALUES
(53, 'provider_approved', 'Approval of Registration Request', '', '&lt;p&gt;Dear [[provider_name]],&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;We&#039;re thrilled to inform you that your request has been approved! This is a significant milestone, and we can&#039;t wait to witness the impact your solutions will have on our operations.&lt;/p&gt;\\r\\n&lt;p&gt;Here are the details you need:&lt;br /&gt;&lt;br /&gt;Provider ID: [[provider_id]]&lt;br /&gt;Company Name: [[provider_name]]&lt;br /&gt;&lt;br /&gt;&lt;/p&gt;\\r\\n&lt;p&gt;As we move forward, please feel free to reach out with any questions or additional information you may require. We&#039;re here to ensure a smooth and successful collaboration.&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;Thank you once again for your outstanding work and dedication. We&#039;re looking forward to a fruitful partnership!&lt;/p&gt;\\r\\n&lt;p&gt;Warm regards,&lt;/p&gt;\\r\\n&lt;p&gt;[[company_logo]]&lt;/p&gt;\\r\\n&lt;p&gt;[[company_contact_info]]&lt;/p&gt;', '', '', '[\\\"provider_name\\\",\\\"provider_id\\\",\\\"provider_name\\\",\\\"company_logo\\\",\\\"company_contact_info\\\"]'),
(54, 'provider_disapproved', 'Rejection of Registration Request', '', '<p>Dear [[provider_name]] </p>,<p>I regret to inform you that your registration request has been declined. After careful review and consideration, we have determined that your offerings do not align with our current needs or standards.</p><p>While we appreciate your interest in partnering with us, we believe it is in both of our best interests to explore other opportunities that better fit our requirements at this time.</p><p>Please know that this decision was not made lightly, and we genuinely value the effort you put into your application. We encourage you to continue pursuing opportunities that align more closely with your expertise and offerings.</p><p>Thank you for your understanding. Should you have any questions or require further clarification, please do not hesitate to reach out.</p><br><p>I wish you all the best in your future endeavors.</p><br><br><p>Warm regards,</p><p>[[company_name]]</p><p>[[company_contact_info]]</p>', '', '', '[\\\"provider_name\\\",\\\"company_name\\\",\\\"company_contact_info\\\"]'),
(55, 'withdraw_request_approved', 'Withdrawal Request Approved', '', '<p>Dear [[Provider Name]],</p><p>We are pleased to inform you that your withdrawal request has been approved. If you have any questions or concerns regarding this transaction, please do not hesitate to contact us.<br> Thank you for choosing our services. We look forward to providing you with excellent service in the future.</p><p>Your Request is for: [[Amount]] [[Currency]].</p><br><br><p>Best Regards,<p><p>[[Company Name]]</p>', '', '', '[\\\"Provider Name\\\",\\\"Amount\\\",\\\"Currency\\\",\\\"Company Name\\\"]'),
(56, 'withdraw_request_disapproved', 'Withdrawal Request Disapproved', '', '<p>Dear [[Provider Name]],</p><p>We regret to inform you that your withdrawal request has been disapproved. If you have any questions or concerns regarding this decision, please do not hesitate to contact us.</p><p> Thank you for choosing our services. We look forward to providing you with excellent service in the future.</p><p>Your Request is for: [[Amount]] [[Currency]].</p><br><br><p>Best Regards,</p><p> [[Company Name]]</p>', '', '', '[\\\"Provider Name\\\",\\\"Amount\\\",\\\"Currency\\\",\\\"Company Name\\\"]'),
(57, 'payment_settlement', 'Payment Settlement', '', '<p>Dear [[provider_name]],</p><p>I am writing to confirm that we have credited the agreed upon amount of [[currency]][[amount]] to your account, as per our agreement. This payment settles the outstanding balance for the services provided by your company.</p><p>We understand the importance of timely payments for maintaining a healthy business relationship, and we strive to meet our payment obligations promptly. Please check your account and confirm that the payment has been received.</p><p>If you have any questions or concerns, please do not hesitate to contact us.</p><p>[[company_contact_info]]</p><br><p>Thank you for your prompt attention to this matter. We look forward to continuing our mutually beneficial partnership.</p> <br><br><p>Best Regards,</p><p>[[company_name]]</p>', '', '', '[\\\"provider_name\\\",\\\"currency\\\",\\\"amount\\\",\\\"company_contact_info\\\",\\\"company_name\\\"]'),
(58, 'service_disapproved', 'Rejection of Service Request', '', '<p>Dear [[Provider Name]],</p><p>We regret to inform you that your request for service approval has been disapproved. After thorough evaluation and consideration, our team has determined that your request does not meet the necessary criteria for approval.</p><br><p>We understand that this decision may be disappointing for you, but please know that we carefully reviewed your request and made the best decision based on our policies and guidelines.</p><p>If you have any questions or concerns regarding the decision, please do not hesitate to reach out to us. We would be happy to discuss any specific concerns that you may have.</p><p>Contact us:</p><p>[[Company Contact Info]]</p><br><br><p>Best Regards,</p><p>[[Company Name]]</p>', '', '', '[\\\"Provider Name\\\",\\\"Company Contact Info\\\",\\\"Company Name\\\"]'),
(59, 'service_approved', 'Approval of Service Request', '', '<p>Dear [[Provider Name]],</p><p>I am pleased to inform you that your request for service approval has been approved. After careful review and consideration, our team has determined that your request meets all the necessary criteria and is eligible for approval.</p><p>Once again, congratulations on your approval status! We look forward to working with you and supporting your goals.</p><p>If you have any questions or concerns, please do not hesitate to contact us.</p><p>Contact Us: [[Company Contact Info]]</p><br><br><p>Best Regards,</p><p>[[Company Name]]</p>', '', '', '[\\\"Provider Name\\\",\\\"Company Contact Info\\\",\\\"Company Name\\\"]'),
(60, 'user_account_active', 'Account activation confirmation', '', '<p>Dear [[user_name]],</p><p>We are pleased to inform you that your account has been successfully activated. You can now log in to your account and start using our services.</p><p>If you have any questions or need any assistance feel free to contact us.</p><p>Thank you again for choosing our services. We look forward to doing business with you again.</p><br><br><p>Best Regards ,</p><p>[[company_name]]</p>', '', '', '[\"user_name\",\"company_name\"]'),
(61, 'user_account_deactive', 'Account Deactivation Confirmation', '', '<div>Dear [[user_name]]</div><div>&nbsp;</div><div>We are sorry to inform you that your account has been deactivated.</div><div>&nbsp;</div><div><div>If you have any questions or need any assistance feel free to contact us.</div></div><div><div><div>&nbsp;</div><div>Thank you again for choosing our services. We look forward to doing business with you again.</div><br><br><div>Best Regards,</div><div>[[company_name]]</div></div></div>', '', '', '[\\\"user_name\\\",\\\"user_id\\\",\\\"user_name\\\",\\\"company_name\\\",\\\"site_url\\\",\\\"company_contact_info\\\",\\\"company_logo\\\",\\\"company_contact_info\\\",\\\"company_logo\\\",\\\"company_name\\\"]'),
(62, 'booking_status_updated', 'Booking Status Updated', '', '&lt;p&gt;Subject: Booking Confirmation&amp;nbsp;&lt;/p&gt;\n&lt;p&gt;Dear [[user_name]],&lt;/p&gt;\n&lt;p&gt;Thank you for choosing [Service Name]. We are pleased to confirm your booking status has been changed.&lt;/p&gt;\n&lt;p&gt;Booking Details:&lt;/p&gt;\n&lt;ul&gt;\n&lt;li&gt;Service Name: [[booking_service_names]]&lt;/li&gt;\n&lt;li&gt;Booking Date: [[booking_date]]&lt;/li&gt;\n&lt;li&gt;Time:[[booking_time]]&lt;/li&gt;\n&lt;li&gt;Address:[[booking_address]]&lt;/li&gt;\n&lt;/ul&gt;\n&lt;p&gt;We look forward to serving you. If you have any questions or need to make changes to your booking, please don&#039;t hesitate to contact us at [Contact Information].&lt;/p&gt;\n&lt;p&gt;Best regards,&lt;/p&gt;\n&lt;p&gt;[[company_name]]&lt;/p&gt;\n&lt;p&gt;[[company_contact_info]]&lt;/p&gt;', '', '', '[\"user_name\",\"booking_service_names\",\"booking_date\",\"booking_time\",\"booking_address\",\"company_name\",\"company_contact_info\"]'),
(63, 'new_booking_confirmation_to_customer', 'Booking Confirmation', '', '<p>Dear [[user_name]],</p><p>Thank you for choosing [[provider_name]]. We are pleased to confirm your booking.Booking Details:</p><br><ul><li>Booking Date:[[booking_date]]</li><li>Time:[[booking_time]]</li><li>Address:[[booking_address]]</li><li>Services include:[[booking_service_names]]</li></ul><br><p>We look forward to serving you. If you have any questions or need to make changes to your booking, please do not hesitate to contact us at [Contact Information].</p><br><br><p>Best regards,</p><p>[[company_name]]</p><p>[[company_contact_info]]</p>', '', '', '[\"user_name\",\"provider_name\",\"booking_date\",\"booking_time\",\"booking_address\",\"company_name\",\"company_contact_info\"]'),
(64, 'new_booking_received_for_provider', 'New Booking Received', '', '<p>Dear [[provider_name]] ,</p><p>We are delighted to inform you that a new booking has been received through our platform.</p><p>Booking Details:</p><br><ul><li>Service:[[booking_service_names]]</li><li>Booking Date: [[booking_date]]</li><li>Time: [[booking_time]]</li><li>Customer:[[user_name]]</li></ul><br><p>Please ensure that you are prepared for the appointment and ready to provide exceptional service to our valued customer.</p><p>If you have any questions or require further information regarding this booking, feel free to reach out to us.</p><p>Thank you for being a part of our service and for your commitment to excellence.</p><br><br><p>Best regards,</p><p>[[company_name]]</p><p>[[company_contact_info]]</p>', '', '', '[\"provider_name\",\"booking_service_names\",\"booking_date\",\"booking_time\",\"user_name\",\"company_name\",\"company_contact_info\"]'),
(65, 'provider_update_information', 'Provider Update Information', '', '<p>Dear [[company_name]]</p><br><p>I hope this message finds you well.</p><p>I wanted to inform you that [Provider Name] has recently updated their details. Please find the updated information below:</p><p>Provider ID: [[provider_id]]</p><br><p>[[provider_name]] has taken the initiative to ensure that their information is accurate and up-to-date in our records. If there are any further steps required from our end regarding this update, please let us know.</p><br><p>Thank you for your attention to this matter.</p><br><br><p>Best regards,</p><p>[[company_name]]</p><p>[[company_contact_info]]</p>', '', '', '[\\\"company_name\\\",\\\"provider_id\\\",\\\"provider_name\\\",\\\"company_name\\\",\\\"company_contact_info\\\"]'),
(66, 'new_provider_registerd', 'New Provider Registered', '', '<p>Subject: New Provider Registered</p><br><p>Dear [[company_name]],</p><br><br><p>I hope this email finds you well. I am pleased to inform you that a new provider has registered with us. Here are the details of the new registration:</p><p>Provider Name:[[provider_name]]</p><p>Provider ID:[[provider_id]]</p><br><p>We welcome [[provider_name]] to our platform and look forward to exploring potential collaborations with them. Kindly review the provided information and proceed with the necessary steps to onboard them into our system.</p><p>If you require any further details or assistance regarding this registration, please do not hesitate to reach out to me.</p><p>Thank you for your attention to this matter.</p><br><br><p>Best regards,</p><p>[[company_name]]</p><p>[[company_contact_info]]</p>', '', '', '[\\\"company_name\\\",\\\"provider_name\\\",\\\"provider_id\\\",\\\"provider_name\\\",\\\"company_name\\\",\\\"company_contact_info\\\"]'),
(67, 'withdraw_request_received', 'Withdrawal Request Received', '', '&lt;p&gt;Subject: Withdrawal Request Received&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;Dear [[company_name]],&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;I hope this email finds you well.&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;I wanted to bring to your attention that we have received a withdrawal request from one of our providers. Here are the details of the request:&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;Provider Name: [[provider_name]]&lt;/p&gt;\\r\\n&lt;p&gt;Provider ID:[[provider_id]]&lt;/p&gt;\\r\\n&lt;p&gt;Amount:[[amount]]&lt;/p&gt;\\r\\n&lt;p&gt;Currency:[[currency]]&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;Please review this withdrawal request at your earliest convenience and proceed with the necessary steps to process it accordingly. If you need any additional information or assistance, please don&#039;t hesitate to reach out to me.&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;Thank you for your attention to this matter.&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\r\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '[\\\"company_name\\\",\\\"provider_name\\\",\\\"provider_id\\\",\\\"amount\\\",\\\"currency\\\"]'),
(68, 'new_rating_given_by_customer', ' New Rating Received from a Customer', 'null', '<p><strong>Subject:</strong> New Rating Received from a Customer !</p>\r\n<p><strong>Dear [[provider_name]],</strong></p>\r\n<p>We wanted to let you know that a customer has recently submitted a rating for your service.</p>\r\n<p>To view the details and feedback, please log in to your provider dashboard at your convenience.</p>\r\n<p>Thank you for your continued commitment to providing excellent service!</p>\r\n<p>Best regards,<br />[[company_name]]</p>\r\n<p>[[company_contact_info]]</p>', '', '', '[\"provider_name\",\"company_name\",\"company_contact_info\"]'),
(69, 'rating_request_to_customer', 'We Value Your Feedback – Please Share Your Rating!', 'null', ' <p><strong>Subject:</strong> We Value Your Feedback – Please Share Your Rating!!</p>\r\n<p><strong>Dear [[user_name]],</strong></p>\r\n<p>We hope you enjoyed your recent experience with us!</p>\r\n<p>Your feedback is incredibly important and helps us to continue improving our services. We would greatly appreciate it if you could take a moment to rate your experience by clicking the link below:</p>\r\n<p> </p>\r\n<p>Thank you for your time and for choosing [[provider_name]]. If you have any additional comments or suggestions, please feel free to reply to this email.</p>\r\n<p>Best regards,<br />[[company_name]]<br /><br /></p>', '', '', '[\"user_name\",\"provider_name\",\"company_name\"]'),
(70, 'cash_collection_by_provider', 'Cash Collection by Provider - Commission Due', '', '<p>Dear [[company_name]],</p>\n    <p>I hope this email finds you well.</p>\n    <p>I wanted to bring to your attention that one of our partners has completed a Cash On Delivery booking. Here are the details of the booking:</p>\n    <p>Provider Name: [[provider_name]]</p>\n    <p>Provider ID: [[provider_id]]</p>\n    <p>Booking ID: [[booking_id]]</p>\n    <p>Commission Amount: [[currency]][[amount]]</p>\n    <p>&nbsp;</p>\n    <p>Please review the cash collection details and process the commission accordingly.</p>\n    <p>&nbsp;</p>\n    <p>Thank you for your attention to this matter.</p>\n    <p>&nbsp;</p>', NULL, NULL, '[\"company_name\",\"provider_name\",\"provider_id\",\"amount\",\"currency\",\"booking_id\",\"company_contact_info\"]'),
(71, 'maintenance_mode', 'System Maintenance - [[company_name]]', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>We would like to inform you that our system is currently under maintenance.</p>\r\n    <p>During this time, some features may be temporarily unavailable. We are working to restore full functionality as soon as possible.</p>\r\n    <p>&nbsp;</p>\r\n    <p>We apologize for any inconvenience this may cause and appreciate your patience.</p>\r\n    <p>&nbsp;</p>\r\n    <p>If you have any urgent concerns, please contact us at [[company_contact_info]].</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your understanding.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', NULL, NULL, '[\"company_name\",\"site_url\",\"company_contact_info\",\"company_logo\"]'),
(72, 'category_removed', 'Category Removed - [[category_name]]', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>We would like to inform you that the category <strong>[[category_name]]</strong> has been removed from our platform.</p>\r\n    <p>Please note that all services associated with this category have been deactivated.</p>\r\n    <p>&nbsp;</p>\r\n    <p>If you have any questions or concerns, please contact us at [[company_contact_info]].</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your understanding.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', NULL, NULL, '[\"company_name\",\"category_name\",\"category_id\",\"company_contact_info\",\"site_url\",\"company_logo\"]'),
(73, 'new_blog', 'New Blog Published - [[blog_title]]', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>We are excited to inform you that a new blog has been published on our platform.</p>\r\n    <p>&nbsp;</p>\r\n    <p><strong>Blog Title:</strong> [[blog_title]]</p>\r\n    <p><strong>Category:</strong> [[blog_category_name]]</p>\r\n    <p><strong>Summary:</strong> [[blog_short_description]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>Click <a href=\"[[blog_url]]\">here</a> to read the full blog post.</p>\r\n    <p>&nbsp;</p>\r\n    <p>We hope you enjoy reading it!</p>\r\n    <p>&nbsp;</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', NULL, NULL, '[\"company_name\",\"blog_id\",\"blog_title\",\"blog_slug\",\"blog_url\",\"blog_short_description\",\"blog_category_name\",\"site_url\",\"company_contact_info\",\"company_logo\"]'),
(74, 'new_category_available', 'New Category Available - [[category_name]]', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>We are excited to announce that a new category <strong>[[category_name]]</strong> is now available on our platform!</p>\r\n    <p>You can now explore and book services in this new category.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Visit our website to discover what\'s new: <a href=\"[[site_url]]\">[[site_url]]</a></p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for being a valued member of our community.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', NULL, NULL, '[\"company_name\",\"category_name\",\"category_id\",\"company_contact_info\",\"site_url\",\"company_logo\"]'),
(75, 'new_custom_job_request', 'New Custom Job Request Created', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>A new custom job request has been created by a customer. The details of the request are as follows:</p>\r\n    <p>Customer Name: [[customer_name]]</p>\r\n    <p>Customer ID: [[customer_id]]</p>\r\n    <p>Custom Job Request ID: [[custom_job_request_id]]</p>\r\n    <p>Service Title: [[service_title]]</p>\r\n    <p>Service Description: [[service_short_description]]</p>\r\n    <p>Category: [[category_name]]</p>\r\n    <p>Price Range: [[currency]][[min_price]] - [[currency]][[max_price]]</p>\r\n    <p>Requested Start Date: [[requested_start_date]]</p>\r\n    <p>Requested Start Time: [[requested_start_time]]</p>\r\n    <p>Requested End Date: [[requested_end_date]]</p>\r\n    <p>Requested End Time: [[requested_end_time]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your attention to this matter.</p>\r\n    <p>&nbsp;</p>', NULL, NULL, '[\"company_name\",\"customer_name\",\"customer_id\",\"custom_job_request_id\",\"service_title\",\"service_short_description\",\"category_name\",\"category_id\",\"min_price\",\"max_price\",\"currency\",\"requested_start_date\",\"requested_start_time\",\"requested_end_date\",\"requested_end_time\",\"company_contact_info\"]'),
(76, 'new_user_registered', 'New User Registered', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>A new user has registered on the platform. The details are as follows:</p>\r\n    <p>User Name: [[user_name]]</p>\r\n    <p>User ID: [[user_id]]</p>\r\n    <p>Email: [[user_email]]</p>\r\n    <p>Phone: [[user_phone]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your attention to this matter.</p>\r\n    <p>&nbsp;</p>', NULL, NULL, '[\"company_name\",\"user_name\",\"user_id\",\"user_email\",\"user_phone\",\"company_contact_info\"]'),
(77, 'privacy_policy_changed', 'Privacy Policy Updated - [[company_name]]', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>We would like to inform you that our privacy policy has been updated.</p>\r\n    <p>We encourage you to review the updated privacy policy to stay informed about how we collect, use, and protect your personal information.</p>\r\n    <p>&nbsp;</p>\r\n    <p>You can view the updated privacy policy by visiting our website: <a href=\"[[site_url]]\">[[site_url]]</a></p>\r\n    <p>&nbsp;</p>\r\n    <p>If you have any questions or concerns about the privacy policy, please contact us at [[company_contact_info]].</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for being a valued member of our community.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', NULL, NULL, '[\"company_name\",\"site_url\",\"company_contact_info\",\"company_logo\"]'),
(78, 'promo_code_added', 'New Promo Code Added: [[promo_code]]', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>A new promo code has been added on the platform.</p>\r\n    <p><strong>Promo Code:</strong> [[promo_code]]</p>\r\n    <p><strong>Provider:</strong> [[provider_name]]</p>\r\n    <p><strong>Discount:</strong> [[discount]][[discount_type_symbol]]</p>\r\n    <p><strong>Minimum Order Amount:</strong> [[minimum_order_amount]]</p>\r\n    <p><strong>Maximum Discount Amount:</strong> [[max_discount_amount]]</p>\r\n    <p><strong>Valid From:</strong> [[start_date]]</p>\r\n    <p><strong>Valid Until:</strong> [[end_date]]</p>\r\n    <p><strong>Number of Users:</strong> [[no_of_users]]</p>\r\n    <p>[[company_logo]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>Please review this promo code and take appropriate action if needed.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your attention to this matter.</p>\r\n    <p>&nbsp;</p>', NULL, NULL, '[\"company_name\",\"provider_name\",\"provider_id\",\"promo_code\",\"promo_code_id\",\"discount\",\"discount_type\",\"discount_type_symbol\",\"minimum_order_amount\",\"max_discount_amount\",\"start_date\",\"end_date\",\"no_of_users\",\"company_contact_info\",\"site_url\"]'),
(79, 'service_updated', 'Service Updated', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>A provider has updated their service information. The details are as follows:</p>\r\n    <p>Provider Name: [[provider_name]]</p>\r\n    <p>Provider ID: [[provider_id]]</p>\r\n    <p>Service ID: [[service_id]]</p>\r\n    <p>Service Title: [[service_title]]</p>\r\n    <p>Category: [[category_name]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>Please review the updated service details in the admin panel.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your attention to this matter.</p>\r\n    <p>&nbsp;</p>', NULL, NULL, '[\"company_name\",\"provider_name\",\"provider_id\",\"service_id\",\"service_title\",\"service_description\",\"category_name\",\"category_id\",\"service_price\",\"service_discounted_price\",\"currency\",\"company_contact_info\"]'),
(80, 'subscription_changed', 'Subscription Changed - [[subscription_name]]', '', '<p>Hello [[provider_name]]!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>We would like to inform you that your subscription has been changed.</p>\r\n    <p>&nbsp;</p>\r\n    <p><strong>Subscription Details:</strong></p>\r\n    <p><strong>Subscription Name:</strong> [[subscription_name]]</p>\r\n    <p><strong>Price:</strong> [[subscription_price]] [[currency]]</p>\r\n    <p><strong>Duration:</strong> [[subscription_duration]]</p>\r\n    <p><strong>Purchase Date:</strong> [[purchase_date]]</p>\r\n    <p><strong>Expiry Date:</strong> [[expiry_date]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>If you have any questions or concerns, please contact us at [[company_contact_info]].</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for being a valued partner.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', NULL, NULL, '[\"company_name\",\"provider_name\",\"provider_id\",\"subscription_name\",\"subscription_id\",\"subscription_price\",\"subscription_duration\",\"expiry_date\",\"purchase_date\",\"currency\",\"company_contact_info\",\"site_url\",\"company_logo\"]'),
(81, 'subscription_removed', 'Subscription Removed - [[subscription_name]]', '', '<p>Hello [[provider_name]]!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>We would like to inform you that your subscription <strong>[[subscription_name]]</strong> has been removed by the admin.</p>\r\n    <p>Your subscription is now deactivated.</p>\r\n    <p>&nbsp;</p>\r\n    <p>If you have any questions or concerns, please contact us at [[company_contact_info]].</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your understanding.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', NULL, NULL, '[\"company_name\",\"provider_name\",\"provider_id\",\"subscription_name\",\"subscription_id\",\"company_contact_info\",\"site_url\",\"company_logo\"]'),
(82, 'terms_and_conditions_changed', 'Terms and Conditions Updated - [[company_name]]', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>We would like to inform you that our terms and conditions have been updated.</p>\r\n    <p>We encourage you to review the updated terms and conditions to stay informed about our policies and your rights and responsibilities.</p>\r\n    <p>&nbsp;</p>\r\n    <p>You can view the updated terms and conditions by visiting our website: <a href=\"[[site_url]]\">[[site_url]]</a></p>\r\n    <p>&nbsp;</p>\r\n    <p>If you have any questions or concerns about the terms and conditions, please contact us at [[company_contact_info]].</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for being a valued member of our community.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', NULL, NULL, '[\"company_name\",\"site_url\",\"company_contact_info\",\"company_logo\"]'),
(83, 'user_blocked', 'User Blocked Notification', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>A user has been blocked on the platform.</p>\r\n    <p><strong>User who blocked:</strong> [[blocker_name]] ([[blocker_type]])</p>\r\n    <p><strong>User who was blocked:</strong> [[blocked_user_name]] ([[blocked_user_type]])</p>\r\n    <p><strong>Blocked User ID:</strong> [[blocked_user_id]]</p>\r\n    <p>[[company_logo]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>Please review this blocking action and take appropriate action if needed.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your attention to this matter.</p>\r\n    <p>&nbsp;</p>', NULL, NULL, '[\"company_name\",\"blocker_name\",\"blocker_type\",\"blocker_id\",\"blocked_user_name\",\"blocked_user_type\",\"blocked_user_id\",\"company_contact_info\",\"site_url\"]'),
(84, 'user_query_submitted', 'New Customer Query Received', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>A new customer query has been submitted via the Contact Us form. The details are as follows:</p>\r\n    <p><strong>Customer Name:</strong> [[customer_name]]</p>\r\n    <p><strong>Customer Email:</strong> [[customer_email]]</p>\r\n    <p><strong>Subject:</strong> [[query_subject]]</p>\r\n    <p><strong>Message:</strong></p>\r\n    <p>[[query_message]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>Please review and respond to this query at your earliest convenience.</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your attention to this matter.</p>\r\n    <p>&nbsp;</p>', NULL, NULL, '[\"company_name\",\"customer_name\",\"customer_email\",\"query_subject\",\"query_message\",\"company_contact_info\",\"site_url\"]'),
(85, 'user_reported', 'User Report Notification', '', '<p>Hello!</p>\r\n    <p>I hope this email finds you well.</p>\r\n    <p>[[notification_message]]</p>\r\n    <p><strong>Reporter:</strong> [[reporter_name]] ([[reporter_type]])</p>\r\n    <p><strong>Reporter ID:</strong> [[reporter_id]]</p>\r\n    <p><strong>Reported User:</strong> [[reported_user_name]] ([[reported_user_type]])</p>\r\n    <p><strong>Reported User ID:</strong> [[reported_user_id]]</p>\r\n    <p><strong>Reason:</strong> [[report_reason]]</p>\r\n    <p><strong>Additional Information:</strong></p>\r\n    <p>[[additional_info]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>[[action_message]]</p>\r\n    <p>&nbsp;</p>\r\n    <p>Thank you for your attention to this matter.</p>\r\n    <p>&nbsp;</p>', NULL, NULL, '[\"company_name\",\"reporter_name\",\"reporter_type\",\"reporter_id\",\"reported_user_name\",\"reported_user_type\",\"reported_user_id\",\"report_reason\",\"report_reason_id\",\"additional_info\",\"notification_message\",\"action_message\",\"company_contact_info\",\"site_url\"]'),
(86, 'added_additional_charges', 'Additional Charges Added - Booking #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We would like to inform you that additional charges have been added to your booking.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Booking Details:</strong></p>\r\n<p>Booking ID: #[[booking_id]]</p>\r\n<p>Provider: [[provider_name]]</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Additional Charges:</strong></p>\r\n<p>[[additional_charges_list]]</p>\r\n<p>Total Additional Charges: [[total_additional_charge]] [[currency]]</p>\r\n<p>Final Total: [[final_total]] [[currency]]</p>\r\n<p>&nbsp;</p>\r\n<p>Please review the additional charges and make payment to complete your booking.</p>\r\n<p>&nbsp;</p>\r\n<p>You can view the details and make payment from your account.</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for your understanding!</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Team</p>', '', '', '[\"booking_id\", \"order_id\", \"total_additional_charge\", \"currency\", \"provider_id\", \"provider_name\", \"customer_id\", \"customer_name\", \"customer_email\", \"additional_charges_list\", \"final_total\", \"company_name\"]'),
(87, 'bid_on_custom_job_request', 'New Bid Received - [[service_title]]', '', '<p>Dear [[customer_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We are pleased to inform you that a provider has placed a bid on your custom job request.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Job Details:</strong></p>\r\n<p>Service Title: [[service_title]]</p>\r\n<p>Description: [[service_short_description]]</p>\r\n<p>Category: [[category_name]]</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Bid Details:</strong></p>\r\n<p>Provider Name: [[provider_name]]</p>\r\n<p>Bid Amount: [[counter_price]] [[currency]]</p>\r\n<p>Duration: [[duration]] days</p>\r\n<p>Cover Note: [[cover_note]]</p>\r\n<p>&nbsp;</p>\r\n<p>You can view the bid details and accept or reject it from your account.</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for using our platform!</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Team</p>', '', '', '[\"custom_job_request_id\", \"service_title\", \"service_short_description\", \"provider_id\", \"provider_name\", \"bid_id\", \"counter_price\", \"currency\", \"duration\", \"cover_note\", \"customer_id\", \"customer_name\", \"customer_email\", \"category_name\", \"company_name\"]'),
(88, 'online_payment_success', 'Payment Successful - Booking #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We are pleased to inform you that your payment has been successfully processed.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Payment Details:</strong></p>\r\n<p>Booking ID: #[[booking_id]]</p>\r\n<p>Amount Paid: [[amount]] [[currency]]</p>\r\n<p>Transaction ID: [[transaction_id]]</p>\r\n<p>Payment Method: [[payment_method]]</p>\r\n<p>Paid At: [[paid_at]]</p>\r\n<p>&nbsp;</p>\r\n<p>Your booking has been confirmed and you can view the details in your account.</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for your payment!</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Team</p>', '', '', '[\"booking_id\", \"order_id\", \"amount\", \"currency\", \"transaction_id\", \"customer_id\", \"customer_name\", \"customer_email\", \"payment_method\", \"paid_at\", \"company_name\"]'),
(89, 'online_payment_failed', 'Payment Failed - Booking #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We regret to inform you that your payment could not be processed.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Payment Details:</strong></p>\r\n<p>Booking ID: #[[booking_id]]</p>\r\n<p>Amount: [[amount]] [[currency]]</p>\r\n<p>Transaction ID: [[transaction_id]]</p>\r\n<p>Payment Method: [[payment_method]]</p>\r\n<p>Failure Reason: [[failure_reason]]</p>\r\n<p>&nbsp;</p>\r\n<p>Please try again or contact our support team if you need assistance.</p>\r\n<p>&nbsp;</p>\r\n<p>If you have any questions, please feel free to reach out to us.</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Support Team</p>', '', '', '[\"booking_id\", \"order_id\", \"amount\", \"currency\", \"transaction_id\", \"customer_id\", \"customer_name\", \"customer_email\", \"failure_reason\", \"payment_method\", \"company_name\"]'),
(90, 'online_payment_pending', 'Payment Pending - Booking #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We have received your payment request and it is currently being processed.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Payment Details:</strong></p>\r\n<p>Booking ID: #[[booking_id]]</p>\r\n<p>Amount: [[amount]] [[currency]]</p>\r\n<p>Transaction ID: [[transaction_id]]</p>\r\n<p>Payment Method: [[payment_method]]</p>\r\n<p>&nbsp;</p>\r\n<p>Your payment is pending confirmation. We will notify you once the payment is successfully processed and your booking is confirmed.</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for your patience.</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Team</p>', '', '', '[\"booking_id\", \"order_id\", \"amount\", \"currency\", \"transaction_id\", \"customer_id\", \"customer_name\", \"customer_email\", \"payment_method\", \"company_name\"]'),
(91, 'payment_refund_executed', 'Refund Processed - Booking #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We are pleased to inform you that your refund has been successfully processed.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Refund Details:</strong></p>\r\n<p>Booking ID: #[[booking_id]]</p>\r\n<p>Refund Amount: [[amount]] [[currency]]</p>\r\n<p>Refund ID: [[refund_id]]</p>\r\n<p>Transaction ID: [[transaction_id]]</p>\r\n<p>Processed Date: [[processed_date]]</p>\r\n<p>&nbsp;</p>\r\n<p>The refunded amount will be credited back to your original payment method. Please allow a few business days for the refund to appear in your account.</p>\r\n<p>&nbsp;</p>\r\n<p>If you have any questions or need further assistance, please feel free to contact our support team.</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for your understanding.</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Support Team</p>', '', '', '[\"booking_id\", \"order_id\", \"amount\", \"currency\", \"refund_id\", \"transaction_id\", \"customer_id\", \"customer_name\", \"processed_date\", \"company_name\"]'),
(92, 'payment_refund_successful', 'Refund Processed Successfully - Order #[[order_id]]', '', '<p>Dear [[customer_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We are pleased to inform you that your refund request has been processed successfully.</p>\r\n<p>&nbsp;</p>\r\n<p>Refund Details:</p>\r\n<p>Order ID: #[[order_id]]</p>\r\n<p>Refund Amount: [[amount]] [[currency]]</p>\r\n<p>Refund ID: [[refund_id]]</p>\r\n<p>Transaction ID: [[transaction_id]]</p>\r\n<p>Processed Date: [[processed_date]]</p>\r\n<p>&nbsp;</p>\r\n<p>The refunded amount will be credited to your original payment method within 3-5 business days, depending on your bank or payment provider.</p>\r\n<p>&nbsp;</p>\r\n<p>If you have any questions or concerns about this refund, please feel free to contact our support team.</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for your patience and understanding.</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Support Team</p>', '', '', '[\"order_id\", \"amount\", \"currency\", \"refund_id\", \"transaction_id\", \"customer_name\", \"customer_email\", \"customer_id\", \"processed_date\", \"company_name\"]'),
(93, 'subscription_expired', 'Subscription Expired - [[subscription_name]]', '', '<p>Dear [[provider_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We hope this email finds you well.</p>\r\n<p>&nbsp;</p>\r\n<p>We wanted to inform you that your subscription has expired.</p>\r\n<p>&nbsp;</p>\r\n<p>Subscription Details:</p>\r\n<p>Subscription Name: [[subscription_name]]</p>\r\n<p>Expiry Date: [[expiry_date]]</p>\r\n<p>Purchase Date: [[purchase_date]]</p>\r\n<p>Duration: [[duration]]</p>\r\n<p>&nbsp;</p>\r\n<p>To continue providing services and receiving bookings, please renew your subscription at your earliest convenience.</p>\r\n<p>&nbsp;</p>\r\n<p>If you have any questions or need assistance with renewing your subscription, please feel free to contact our support team.</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for being a valued provider on our platform.</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Support Team</p>', '', '', '[\"subscription_id\", \"subscription_name\", \"provider_id\", \"provider_name\", \"expiry_date\", \"purchase_date\", \"duration\", \"company_name\"]'),
(94, 'subscription_payment_successful', 'Subscription Payment Successful - [[subscription_name]]', '', '<p>Dear [[provider_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We are pleased to inform you that your subscription payment has been successfully processed.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Payment Details:</strong></p>\r\n<p>Subscription Name: [[subscription_name]]</p>\r\n<p>Amount Paid: [[amount]] [[currency]]</p>\r\n<p>Transaction ID: [[transaction_id]]</p>\r\n<p>Purchase Date: [[purchase_date]]</p>\r\n<p>Expiry Date: [[expiry_date]]</p>\r\n<p>&nbsp;</p>\r\n<p>Your subscription is now active and you can start receiving bookings.</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for your subscription!</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Team</p>', '', '', '[\"subscription_id\", \"subscription_name\", \"provider_id\", \"provider_name\", \"amount\", \"currency\", \"transaction_id\", \"purchase_date\", \"expiry_date\", \"company_name\"]'),
(95, 'subscription_payment_failed', 'Subscription Payment Failed - [[subscription_name]]', '', '<p>Dear [[provider_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We regret to inform you that your subscription payment could not be processed.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Payment Details:</strong></p>\r\n<p>Subscription Name: [[subscription_name]]</p>\r\n<p>Amount: [[amount]] [[currency]]</p>\r\n<p>Transaction ID: [[transaction_id]]</p>\r\n<p>Failure Reason: [[failure_reason]]</p>\r\n<p>&nbsp;</p>\r\n<p>Please try again or contact our support team if you need assistance.</p>\r\n<p>&nbsp;</p>\r\n<p>If you have any questions, please feel free to reach out to us.</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Support Team</p>', '', '', '[\"subscription_id\", \"subscription_name\", \"provider_id\", \"provider_name\", \"amount\", \"currency\", \"transaction_id\", \"failure_reason\", \"company_name\"]'),
(96, 'subscription_payment_pending', 'Subscription Payment Pending - [[subscription_name]]', '', '<p>Dear [[provider_name]],</p>\r\n<p>&nbsp;</p>\r\n<p>We have received your subscription payment request and it is currently being processed.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Payment Details:</strong></p>\r\n<p>Subscription Name: [[subscription_name]]</p>\r\n<p>Amount: [[amount]] [[currency]]</p>\r\n<p>Transaction ID: [[transaction_id]]</p>\r\n<p>&nbsp;</p>\r\n<p>Your payment is pending confirmation. We will notify you once the payment is successfully processed and your subscription is activated.</p>\r\n<p>&nbsp;</p>\r\n<p>Thank you for your patience.</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] Team</p>', '', '', '[\"subscription_id\", \"subscription_name\", \"provider_id\", \"provider_name\", \"amount\", \"currency\", \"transaction_id\", \"company_name\"]'),
(97, 'subscription_purchased', 'New Subscription Purchase - [[provider_name]]', '', '<p>Dear Admin,</p>\r\n<p>&nbsp;</p>\r\n<p>We wanted to inform you that a provider has purchased a new subscription.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Subscription Purchase Details:</strong></p>\r\n<p>Provider Name: [[provider_name]]</p>\r\n<p>Provider ID: [[provider_id]]</p>\r\n<p>Subscription Name: [[subscription_name]]</p>\r\n<p>Purchase Date: [[purchase_date]]</p>\r\n<p>Expiry Date: [[expiry_date]]</p>\r\n<p>Duration: [[duration]] days</p>\r\n<p>Amount Paid: [[amount]] [[currency]]</p>\r\n<p>Transaction ID: [[transaction_id]]</p>\r\n<p>&nbsp;</p>\r\n<p>This subscription is now active and the provider can start receiving bookings.</p>\r\n<p>&nbsp;</p>\r\n<p>Best regards,</p>\r\n<p>[[company_name]] System</p>', '', '', '[\"subscription_id\", \"subscription_name\", \"provider_id\", \"provider_name\", \"purchase_date\", \"expiry_date\", \"duration\", \"amount\", \"currency\", \"transaction_id\", \"company_name\"]'),
(98, 'booking_confirmed', 'Booking Confirmed - Order #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n    <p>Your booking has been confirmed!</p>\r\n    <p><strong>Booking Details:</strong></p>\r\n    <ul>\r\n        <li>Booking ID: #[[booking_id]]</li>\r\n        <li>Status: [[booking_status]]</li>\r\n        <li>Service Date: [[date_of_service]]</li>\r\n        <li>Service Time: [[service_time]]</li>\r\n        <li>Provider: [[provider_name]]</li>\r\n        <li>Total Amount: [[currency]] [[final_total]]</li>\r\n    </ul>\r\n    <p>Thank you for choosing our services.</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', '', '', '[\"booking_id\",\"booking_status\",\"customer_name\",\"provider_name\",\"date_of_service\",\"service_time\",\"final_total\",\"currency\",\"company_name\"]'),
(99, 'booking_rescheduled', 'Booking Rescheduled - Order #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n    <p>Your booking has been rescheduled.</p>\r\n    <p><strong>Updated Booking Details:</strong></p>\r\n    <ul>\r\n        <li>Booking ID: #[[booking_id]]</li>\r\n        <li>Status: [[booking_status]]</li>\r\n        <li>New Service Date: [[date_of_service]]</li>\r\n        <li>New Service Time: [[service_time]]</li>\r\n        <li>Provider: [[provider_name]]</li>\r\n        <li>Total Amount: [[currency]] [[final_total]]</li>\r\n    </ul>\r\n    <p>If you have any questions, please contact us.</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', '', '', '[\"booking_id\",\"booking_status\",\"customer_name\",\"provider_name\",\"date_of_service\",\"service_time\",\"final_total\",\"currency\",\"company_name\"]'),
(100, 'booking_cancelled', 'Booking Cancelled - Order #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n    <p>Your booking has been cancelled.</p>\r\n    <p><strong>Booking Details:</strong></p>\r\n    <ul>\r\n        <li>Booking ID: #[[booking_id]]</li>\r\n        <li>Status: [[booking_status]]</li>\r\n        <li>Service Date: [[date_of_service]]</li>\r\n        <li>Provider: [[provider_name]]</li>\r\n    </ul>\r\n    <p>If you have any questions or concerns, please contact us.</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', '', '', '[\"booking_id\",\"booking_status\",\"customer_name\",\"provider_name\",\"date_of_service\",\"company_name\"]'),
(101, 'booking_completed', 'Booking Completed - Order #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n    <p>Your booking has been completed successfully!</p>\r\n    <p><strong>Booking Details:</strong></p>\r\n    <ul>\r\n        <li>Booking ID: #[[booking_id]]</li>\r\n        <li>Status: [[booking_status]]</li>\r\n        <li>Service Date: [[date_of_service]]</li>\r\n        <li>Provider: [[provider_name]]</li>\r\n        <li>Total Amount: [[currency]] [[final_total]]</li>\r\n    </ul>\r\n    <p>Thank you for using our services. We hope you had a great experience!</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', '', '', '[\"booking_id\",\"booking_status\",\"customer_name\",\"provider_name\",\"date_of_service\",\"final_total\",\"currency\",\"company_name\"]'),
(102, 'booking_started', 'Service Started - Order #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n    <p>Your service has started!</p>\r\n    <p><strong>Booking Details:</strong></p>\r\n    <ul>\r\n        <li>Booking ID: #[[booking_id]]</li>\r\n        <li>Status: [[booking_status]]</li>\r\n        <li>Service Date: [[date_of_service]]</li>\r\n        <li>Service Time: [[service_time]]</li>\r\n        <li>Provider: [[provider_name]]</li>\r\n    </ul>\r\n    <p>Your service provider has started working on your booking.</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', '', '', '[\"booking_id\",\"booking_status\",\"customer_name\",\"provider_name\",\"date_of_service\",\"service_time\",\"company_name\"]'),
(103, 'booking_ended', 'Booking Ended - Order #[[booking_id]]', '', '<p>Dear [[customer_name]],</p>\r\n    <p>Your booking has ended.</p>\r\n    <p><strong>Booking Details:</strong></p>\r\n    <ul>\r\n        <li>Booking ID: #[[booking_id]]</li>\r\n        <li>Status: [[booking_status]]</li>\r\n        <li>Service Date: [[date_of_service]]</li>\r\n        <li>Provider: [[provider_name]]</li>\r\n        <li>Total Amount: [[currency]] [[final_total]]</li>\r\n    </ul>\r\n    <p>[[status_message]]</p>\r\n    <p>If you have any questions, please contact us.</p>\r\n    <p>Best regards,<br>[[company_name]]</p>', '', '', '[\"booking_id\",\"booking_status\",\"customer_name\",\"provider_name\",\"date_of_service\",\"final_total\",\"currency\",\"status_message\",\"company_name\"]'),
(104, 'provider_edits_service_details', 'Provider [[provider_name]] Has Edited Service Details', '', '<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Service Details Edited</title>\n</head>\n<body style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;\">\n    <div style=\"background-color: #f8f9fa; padding: 20px; border-radius: 5px; margin-bottom: 20px;\">\n        <h2 style=\"color: #2c3e50; margin-top: 0;\">Service Details Edited</h2>\n        <p>Hello Admin,</p>\n        <p>The provider <strong>[[provider_name]]</strong> has edited the details of their service.</p>\n    </div>\n    \n    <div style=\"background-color: #ffffff; border: 1px solid #dee2e6; padding: 20px; border-radius: 5px; margin-bottom: 20px;\">\n        <h3 style=\"color: #495057; margin-top: 0;\">Service Information</h3>\n        <table style=\"width: 100%; border-collapse: collapse;\">\n            <tr>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6; font-weight: bold; width: 40%;\">Service ID:</td>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6;\">[[service_id]]</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6; font-weight: bold;\">Service Title:</td>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6;\">[[service_title]]</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6; font-weight: bold;\">Category:</td>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6;\">[[category_name]]</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6; font-weight: bold;\">Price:</td>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6;\">[[currency]] [[service_price]]</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6; font-weight: bold;\">Discounted Price:</td>\n                <td style=\"padding: 8px; border-bottom: 1px solid #dee2e6;\">[[currency]] [[service_discounted_price]]</td>\n            </tr>\n            <tr>\n                <td style=\"padding: 8px; font-weight: bold;\">Provider:</td>\n                <td style=\"padding: 8px;\">[[provider_name]] (ID: [[provider_id]])</td>\n            </tr>\n        </table>\n    </div>\n    \n    <div style=\"background-color: #e7f3ff; padding: 15px; border-radius: 5px; border-left: 4px solid #0066cc;\">\n        <p style=\"margin: 0;\"><strong>Note:</strong> Please review the updated service details in the admin panel to ensure all changes comply with your platform guidelines.</p>\n    </div>\n    \n    <div style=\"margin-top: 20px; padding-top: 20px; border-top: 1px solid #dee2e6; text-align: center; color: #6c757d; font-size: 12px;\">\n        <p>This is an automated notification from [[company_name]].</p>\n        <p>Visit <a href=\"[[site_url]]\" style=\"color: #0066cc;\">[[site_url]]</a> for more information.</p>\n        <p>[[company_contact_info]]</p>\n    </div>\n</body>\n</html>', NULL, NULL, '[\"provider_name\",\"provider_id\",\"service_id\",\"service_title\",\"service_description\",\"category_name\",\"category_id\",\"service_price\",\"service_discounted_price\",\"currency\",\"company_name\",\"site_url\",\"company_contact_info\"]');
INSERT INTO `email_templates` (`id`, `type`, `subject`, `to`, `template`, `bcc`, `cc`, `parameters`) VALUES
(105, 'send_otp', 'Your OTP Code', '', '<html><body>\n                <h2>Your OTP Code</h2>\n                <p>Hello,</p>\n                <p>Your OTP code is: <strong style=\"font-size: 24px; color: #007bff;\">[[otp]]</strong></p>\n                <p>Please do not share this code with anyone.</p>\n                <p>This code will expire in a few minutes.</p>\n                <p>Best regards,<br>[[company_name]]</p>\n            </body></html>', NULL, NULL, '[\"otp\",\"company_name\"]');
